from level_styles import category_appearance
for group in GROUPS:
    for item in group['levels']:
        item['appearance']=category_appearance(item['kind'])
CATALOG = {item['kind']:item for group in GROUPS for item in group['levels']}
# Preserve the original ordering for callers that use the existing families.
LEVEL_TYPES = ('resistance','support','gap','window','premarket_high','premarket_low',
               'former_support','former_resistance','previous_high','previous_low','previous_close',
               'day_high','day_low','failed_rally','previous_open','event_close','prior_premarket_high','support_zone','ascending_support','descending_resistance','event_high')
LABEL_ORDER=('premarket_high','premarket_low','gap','window','resistance','support','former_support','former_resistance')+LEVEL_TYPES[8:]
LEVEL_NAMES = {kind:CATALOG[kind]['label'] for kind in LABEL_ORDER}
